fn find_max(nums: Vec<i32>) -> i32 {
    // Since the input is guaranteed non-empty, we can safely take the first element as the initial max.
    let mut iter = nums.into_iter();
    let mut max_val = iter.next().unwrap();

    // Iterate through the rest of the elements, updating max_val whenever we find a larger one.
    for num in iter {
        if num > max_val {
            max_val = num;
        }
    }

    max_val
}

